INSERT INTO `ps_cms_lang` (`id_cms`, `id_lang`, `id_shop`, `meta_title`, `head_seo_title`, `meta_description`, `meta_keywords`, `content`, `link_rewrite`) VALUES
(1, 1, 1, 'Delivery', '', 'Our terms and conditions of delivery', 'conditions, delivery, delay, shipment, pack', '<h2>Shipments and returns</h2><h3>Your pack shipment</h3><p>Packages are generally dispatched within 2 days after receipt of payment and are shipped via UPS with tracking and drop-off without signature. If you prefer delivery by UPS Extra with required signature, an additional cost will be applied, so please contact us before choosing this method. Whichever shipment choice you make, we will provide you with a link to track your package online.</p><p>Shipping fees include handling and packing fees as well as postage costs. Handling fees are fixed, whereas transport fees vary according to total weight of the shipment. We advise you to group your items in one order. We cannot group two distinct orders placed separately, and shipping fees will apply to each of them. Your package will be dispatched at your own risk, but special care is taken to protect fragile objects.<br /><br />Boxes are amply sized and your items are well-protected.</p>', 'delivery'),
(2, 1, 1, 'Legal Notice', '', 'Legal notice', 'notice, legal, credits', '<h2>Legal</h2><h3>Credits</h3><p>Concept and production:</p><p>This Web site was created using <a href=\"http://www.prestashop.com\">PrestaShop</a>&trade; open-source software.</p>', 'legal-notice'),
(3, 1, 1, 'Terms and conditions of use', '', 'Our terms and conditions of use', 'conditions, terms, use, sell', '<h2>Your terms and conditions of use</h2><h3>Rule 1</h3><p>Here is the rule 1 content</p>\r\n<h3>Rule 2</h3><p>Here is the rule 2 content</p>\r\n<h3>Rule 3</h3><p>Here is the rule 3 content</p>', 'terms-and-conditions-of-use'),
(4, 1, 1, 'About us', '', 'Learn more about us', 'about us, informations', '<h2>About us</h2>\r\n<h3>Our company</h3><p>Our company</p>\r\n<h3>Our team</h3><p>Our team</p>\r\n<h3>Informations</h3><p>Informations</p>', 'about-us'),
(5, 1, 1, 'Secure payment', '', 'Our secure payment mean', 'secure payment, ssl, visa, mastercard, paypal', '<h2>Secure payment</h2>\r\n<h3>Our secure payment</h3><p>With SSL</p>\r\n<h3>Using Visa/Mastercard/Paypal</h3><p>About this services</p>', 'secure-payment'),
(6, 1, 1, 'Gwarancja', NULL, 'Informacje o gwarancji', 'gwarancja', '<h1>Gwarancja</h1><p>TreÅ›Ä‡ strony dotyczÄ…cej gwarancji.</p>', 'gwarancja'),
(7, 1, 1, 'Trekking', NULL, 'Informacje o trekkingu', 'trekking', '<h1>Trekking</h1><p>TreÅ›Ä‡ strony o trekkingu.</p>', 'trekking'),
(8, 1, 1, 'Gory', NULL, 'Informacje o gorach', 'gory', '<h1>GÃ³ry</h1><p>TreÅ›Ä‡ strony o gorach.</p>', 'gory'),
(9, 1, 1, 'Apteczka', NULL, 'Informacje o apteczce', 'apteczka', '<h1>Apteczka</h1><p>TreÅ›Ä‡ strony o apteczce.</p>', 'apteczka'),
(10, 1, 1, 'Kajak', NULL, 'Informacje o kajakach', 'kajak', '<h1>Kajak</h1><p>TreÅ›Ä‡ strony o kajakach.</p>', 'kajak'),
(11, 1, 1, 'Skitury', NULL, 'Informacje o Skiturach', 'skitury', '<h1>Skitury</h1><p>TreÅ›Ä‡ strony o skiturach.</p>', 'skitury'),
(12, 1, 1, 'Tropiki', NULL, 'Informacje o tropikach', 'tropiki', '<h1>Tropiki</h1><p>TreÅ›Ä‡ strony o Tropikach.</p>', 'tropiki'),
(13, 1, 1, 'Skaly', NULL, 'Informacje o skalach', 'skaly', '<h1>SkaÅ‚y</h1><p>TreÅ›Ä‡ strony o skalach.</p>', 'skaly'),
(14, 1, 1, 'Camping', NULL, 'Informacje o camp', 'camping', '<h1>Camping</h1><p>TreÅ›Ä‡ strony o camp.</p>', 'camping'),
(15, 1, 1, 'Camino', NULL, 'Informacje o camino', 'camino', '<h1>camino</h1><p>TreÅ›Ä‡ strony o camino.</p>', 'camino'),
(16, 1, 1, 'Warszawa', NULL, 'lokalizacja Warszawa', 'warszawa', '<h1>warszawa</h1><p>TreÅ›Ä‡ strony o warszawa.</p>', 'warszawa'),
